<template><div class="demo-dashboard"><WorkspaceHero eyebrow="GROWTH IN ORBIT" :title="user.role==='student'?'每一份努力，都留下成长的轨迹':'让评价有据，让指导有方向'" description="这是使用示例数据的交互工作区。通过切换身份，体验一份申报如何流转为反馈与成长行动。"/><div class="demo-summary"><article v-for="item in stats" :key="item.label"><span>{{item.label}}</span><strong>{{item.value}}<small>{{item.unit}}</small></strong><p>{{item.note}}</p></article></div><div class="overview-grid"><section class="card journey"><div class="section-head"><h2>一次完整的成长旅程</h2><span>体验路径</span></div><router-link v-for="(item,index) in steps" :key="item.to" :to="item.to"><span class="journey-number">0{{index+1}}</span><div><strong>{{item.title}}</strong><p>{{item.description}}</p></div><span class="arrow">↗</span></router-link></section><section class="card radar-panel"><div class="section-head"><h2>五育表现</h2><span>示例成绩</span></div><div ref="chart" class="radar-chart" role="img" aria-label="示例五育表现雷达图"></div><router-link to="/evaluation">查看分数与计算过程 →</router-link><p>不同维度上限不同，图中按各维度满分归一化展示。</p></section></div><section class="card guide"><div><span>推荐体验</span><h2>从一个待办开始</h2><p>先补充一份申报，或核验一项成长任务。演示记录会随你的操作更新。</p></div><el-button type="primary" @click="router.push('/work-items')">打开我的待办 →</el-button></section></div></template>
<script setup>
import {computed,ref,onMounted,onBeforeUnmount} from 'vue';import {useRouter} from 'vue-router';import * as echarts from 'echarts';import WorkspaceHero from '@/components/WorkspaceHero.vue';import {useUserStore} from '@/stores/user';import {currentState,calculate,workItems} from './data.js';
const router=useRouter();const user=useUserStore();const state=currentState();const score=calculate();const todo=workItems(user.role);const chart=ref();let instance;let resize;
const stats=computed(()=>[{label:'本期综测',value:score.totalScore,unit:'分',note:'示例数据实时计算'},{label:'成果记录',value:state.applications.length,unit:'项',note:'包含草稿和待审核记录'},{label:'待处理事项',value:todo.counts.total,unit:'项',note:'申报、成长任务与提醒'},{label:'成长行动',value:state.plan?.tasks.filter(t=>t.status==='completed').length||0,unit:'/ 3',note:'已完成教师核验的任务'}]);
const steps=computed(()=>user.role==='student'?[{to:'/rule-guide',title:'查规则，找准申报入口',description:'查看示例规则原文、分数上限和准备要求。'},{to:'/my-applications',title:'补材料，让经历有据可查',description:'继续填写内置草稿，体验同成果提醒。'},{to:'/growth-plan',title:'记行动，把评价变成进步',description:'补充过程记录，提交教师核验。'}]:[{to:'/approval',title:'核对证据，给出清晰意见',description:'预览内置示例证书，体验通过或退回操作。'},{to:'/growth-plan?studentId=9',title:'核验成长，留下过程反馈',description:'查看学生记录并确认完成或退回补充。'},{to:user.role==='college_admin'?'/evaluation-config':'/evaluation',title:'解释计分，理解规则影响',description:'查看各维度结果与实际计算过程。'}]);
onMounted(()=>{instance=echarts.init(chart.value);instance.setOption({radar:{indicator:Object.values(score.modules).map(m=>({name:m.name,max:100})),radius:'65%',axisName:{color:'#718299',fontSize:12},splitArea:{areaStyle:{color:['#fff','#f4f8fd']}},splitLine:{lineStyle:{color:'#e0e9f4'}}},series:[{type:'radar',data:[{value:Object.values(score.modules).map(m=>Math.max(0,m.score/m.max*100)),name:'示例五育表现'}],lineStyle:{color:'#277bd3',width:2},itemStyle:{color:'#277bd3'},areaStyle:{color:'rgba(39,123,211,.18)'}}],tooltip:{trigger:'item'}});resize=()=>instance.resize();window.addEventListener('resize',resize);});onBeforeUnmount(()=>{window.removeEventListener('resize',resize);instance?.dispose();});
</script>
<style scoped>
.demo-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin:22px 0;}.demo-summary article{padding:22px;background:#fff;border:1px solid #e0e8f3;border-radius:14px;}.demo-summary article>span{font-size:12px;color:#6a7d95;}.demo-summary strong{display:block;font:700 34px/1.6 ui-monospace,monospace;color:#1e548e;}.demo-summary small{font:12px sans-serif;color:#8294aa;margin-left:8px;}.demo-summary p{font-size:11px;color:#8494a9;margin:3px 0;}.overview-grid{display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,1fr);gap:22px;}.journey,.radar-panel{padding:24px;}.section-head{display:flex;justify-content:space-between;gap:12px;align-items:center;}.section-head h2,.guide h2{font-size:18px;margin:0;color:#203c5c;}.section-head span,.guide>div>span{font-size:11px;color:#8193aa;}.journey>a{display:flex;align-items:center;gap:18px;text-decoration:none;color:#1e3d60;padding:27px 0;border-bottom:1px solid #e8eef6;}.journey>a:last-child{border:0;}.journey-number{font:25px ui-monospace,monospace;color:#a6bdd5;}.journey strong{font-size:14px;}.journey p{font-size:12px;color:#8292a7;line-height:1.8;margin:6px 0;}.arrow{margin-left:auto;color:#2878cd;}.radar-chart{height:280px;width:100%;}.radar-panel>a{font-size:12px;color:#2878cd;}.radar-panel>p{font-size:11px;color:#8292a7;line-height:1.8;}.guide{margin-top:22px;padding:26px;display:flex;justify-content:space-between;align-items:center;gap:20px;background:linear-gradient(110deg,#fff,#eef6ff);}.guide h2{margin:9px 0;}.guide p{font-size:12px;line-height:1.8;color:#7589a2;}@media(max-width:850px){.demo-summary{grid-template-columns:repeat(2,minmax(0,1fr));}.overview-grid{grid-template-columns:minmax(0,1fr);}}@media(max-width:520px){.demo-summary{gap:10px;}.demo-summary article{padding:16px;}.demo-summary strong{font-size:29px;}.journey,.radar-panel{padding:20px 16px;}.guide{align-items:flex-start;flex-direction:column;padding:20px;}}
</style>
